  group('determinism and normalization', () {
    test('same seed renders the same SVG every time', () {
      expect(blobatarSvg('alain'), blobatarSvg('alain'));
      expect(blobatarSvg('🦊6🌱'), blobatarSvg('🦊6🌱'));
    });

    test('different seeds render different SVGs', () {
      expect(blobatarSvg('alain'), isNot(blobatarSvg('alaim')));
      expect(blobatarSvg('user-0'), isNot(blobatarSvg('user-1')));
    });

    test('names are normalized: case, trim and NFC agree', () {
      expect(blobatarSvg('Alain@Example.com'), blobatarSvg('alain@example.com'));
      expect(blobatarSvg('  alain  '), blobatarSvg('alain'));
      // 'é' precomposed vs 'e' + combining accent (decomposed).
      expect(blobatarSvg('caf\u00e9'), blobatarSvg('cafe\u0301'));
    });

    test('normalize:false hashes the raw string', () {
      expect(
        blobatarSvg('Alain', normalize: false),
        isNot(blobatarSvg('alain', normalize: false)));
    });

    test('output is a well-formed svg document', () {
      final svg = blobatarSvg('alain');
      expect(svg.startsWith('<svg xmlns="http://www.w3.org/2000/svg"'), isTrue);
      expect(svg.endsWith('</svg>'), isTrue);
      expect(svg.contains('viewBox="0 0 100 100"'), isTrue);
    });

    test('size emits width and height', () {
      expect(blobatarSvg('alain', size: 64).contains('width="64" height="64"'), isTrue);
      expect(blobatarSvg('alain').contains('width='), isFalse);
    });

    test('blobatarUri round-trips through percent-encoding', () {
      final uri = blobatarUri('alain');
      expect(uri.startsWith('data:image/svg+xml,'), isTrue);
      expect(Uri.decodeComponent(uri.substring('data:image/svg+xml,'.length)), blobatarSvg('alain'));
    });
  });

  group('Blobatar widget', () {
    testWidgets('renders an SvgPicture sized to size', (tester) async {
      await tester.pumpWidget(const Center(child: Blobatar(seed: 'alain', size: 64)));
      expect(find.byType(Blobatar), findsOneWidget);
      final Blobatar widget = tester.widget(find.byType(Blobatar));
      expect(widget.toSvg(), blobatarSvg('alain', size: 64));
    });
  });
}
